        descripcion:'Cuando Janis llegó a mi apartamento antes de Jim (Marshall), inventamos un plan para ser serios, sin importar lo que Jim dijo o hizo. Lo que siguió fueron horas de Jim diciendo: "Vamos, chicas, sonrían. Intentó contar chistes y ser el tipo de tonto, pero Janis y yo continuamos haciendo la rutina seria, pensando que Jim finalmente la perdería y renunciaría. Él no lo hizo, nosotros no, y la fotografía de Grace y Janis lado a lado, de aspecto sombrío ha aparecido en calendarios, libros y carteles de todo el mundo'
