        imagen:'3154.jpg',
        titulo:'Miles Davis',
        personas:'Miles Davis',
        origen:'Facebook',
        descripcion:'La pareja paseaba por el Sena, de la mano, parándose para dar un beso. Un idilio impensable en los Estados Unidos, donde las relaciones interraciales estaban prohibidas. Miles disfrutó de una nueva libertad en Francia. "Nunca me había sentido así en mi vida", escribió en su autobiografía. "Era la libertad de estar en Francia y ser tratado como un ser humano. "Juliette fue probablemente la primera mujer que amé como un ser humano igualitario. Ella era una persona hermosa. Tuvimos que comunicarnos unos con otros a través de expresiones y lenguaje corporal... Era abril en París. Sí, estaba enamorado'
