        personas:'Roy Buchanan',
        origen:'Facebook',
        descripcion:'Roy Buchanan (1939-1988), "el mejor guitarrista desconocido del mundo", tal como lo apodaron en la década de los años setenta, dejó un legado inconmensurable. Su estilo fue único e inigualable, era muy poco ortodoxo para las escalas y utilizaba una depurada técnica en la digitación, combinando el uso de sus dedos con la púa. Lograba sacar unos agudos muy intensos, casi hipnóticos, concertando la melancolía del blues con cierto toque country. Roy Buchanan marcó un antes y un después en la historia de la guitarra eléctrica con la Telecaster como emblema.'
